//! Account-object family: CheckCreate, CheckCash, CheckCancel, TicketCreate, DepositPreauth,
//! SignerListSet, Clawback. Each `*_tx` builds the typed `xrpl::models` struct once; the
//! `*_json` / `*_sign` pair (generated by `json_and_sign!`) are its simulate / signed forms.
//!
//! Left out because the spec / crate cannot express them here:
//! - DepositPreauth `AuthorizeCredentials` / `UnauthorizeCredentials` (credential lists; belongs
//!   with the Credentials family).
//! - SignerListSet `WalletLocator` per entry (no field in the crate's `SignerEntry`).
//! - Clawback of an MPT (`Holder`): the shared amount parser only reads XRP / `CUR:issuer:value`,
//!   so only the issued-currency form is offered.

use color_eyre::eyre::eyre;
use serde_json::Value;
use xrpl::models::Model;
use xrpl::models::transactions::check_cancel::CheckCancel;
use xrpl::models::transactions::check_cash::CheckCash;
use xrpl::models::transactions::check_create::CheckCreate;
use xrpl::models::transactions::clawback::Clawback;
use xrpl::models::transactions::deposit_preauth::DepositPreauth;
use xrpl::models::transactions::signer_list_set::{SignerEntry, SignerListSet};
use xrpl::models::transactions::ticket_create::TicketCreate;

use super::{Confirm, FieldKind, FieldSpec, Fields, TxSpec, common_fields, val};
use crate::signing::{parse_offer_amount, sign_blob};

const FAMILY: &str = "Account objects";
const ID_LEN: usize = 64;
/// rippled `maxTicketCount` (an account may hold at most 250 Tickets).
const MAX_TICKETS: u32 = 250;
/// rippled `maxSignerListSize` (post-`ExpandedSignerList` is 32 but the crate model caps at 8).
const MAX_SIGNERS: usize = 8;
/// 8 × (34-char address + `:` + 5-digit weight + separator) with slack.
const MAX_SIGNER_TEXT: usize = 400;

pub static SPECS: &[TxSpec] = &[
    CHECK_CREATE,
    CHECK_CASH,
    CHECK_CANCEL,
    TICKET_CREATE,
    DEPOSIT_PREAUTH,
    SIGNER_LIST_SET,
    CLAWBACK,
];

fn eyre_model<E: std::fmt::Debug>(e: E) -> color_eyre::Report {
    eyre!("{e:?}")
}

fn to_json<T: serde::Serialize>(tx: &T, what: &str) -> color_eyre::Result<Value> {
    serde_json::to_value(tx).map_err(|e| eyre!("{what} tx_json: {e}"))
}

fn required<'a>(fields: &'a Fields, name: &str) -> color_eyre::Result<&'a str> {
    val(fields, name).ok_or_else(|| eyre!("{name}: required"))
}

fn address(fields: &Fields, name: &str) -> Option<String> {
    val(fields, name).map(str::to_string)
}

fn upper(fields: &Fields, name: &str) -> Option<String> {
    val(fields, name).map(str::to_ascii_uppercase)
}

fn uint(fields: &Fields, name: &str) -> color_eyre::Result<Option<u32>> {
    val(fields, name)
        .map(|v| v.parse::<u32>().map_err(|e| eyre!("{name}: {e}")))
        .transpose()
}

fn no_check(_: &Fields) -> Result<(), String> {
    Ok(())
}

/// `<name>_json` (unsigned, model-validated) and `<name>_sign` (typed signer) from `<name>_tx`.
macro_rules! json_and_sign {
    ($tx:ident, $json:ident, $sign:ident, $what:literal) => {
        fn $json(account: &str, f: &Fields, sequence: u32) -> color_eyre::Result<Value> {
            let tx = $tx(account, f, sequence, None)?;
            tx.validate().map_err(eyre_model)?;
            to_json(&tx, $what)
        }

        fn $sign(
            wallet: &xrpl::wallet::Wallet,
            account: &str,
            f: &Fields,
            sequence: u32,
            fee: u32,
            lls: u32,
        ) -> color_eyre::Result<String> {
            let mut tx = $tx(account, f, sequence, Some((fee, lls)))?;
            sign_blob!(tx, wallet)
        }
    };
}

