// -------------------------------------------------------------- SignerListSet

pub const SIGNER_LIST_SET: TxSpec = TxSpec {
    tx_type: "SignerListSet",
    family: FAMILY,
    summary: "set / replace / delete the multi-sign list ⚠ can lock the account",
    fields: &[
        FieldSpec {
            name: "SignerQuorum",
            kind: FieldKind::Uint(u32::MAX),
            required: true,
            help: "weight needed to multi-sign (≤ sum of weights); 0 deletes the list",
            default: "",
        },
        FieldSpec {
            name: "SignerEntries",
            kind: FieldKind::Text(MAX_SIGNER_TEXT),
            required: false,
            help: "1..8 of addr:weight (weight 1..65535), comma-separated; blank when deleting",
            default: "",
        },
    ],
    confirm: Some(Confirm {
        phrase: "SIGNERS",
        hint: "Replaces or deletes the multi-sign list; a wrong list can lock the account if the master key is disabled",
    }),
    check: signer_list_check,
    build_json: signer_list_json,
    sign: signer_list_sign,
};

/// `addr:weight` list → entries, checking address, weight, count and uniqueness.
fn parse_signer_entries(text: &str) -> Result<Vec<(String, u16)>, String> {
    let mut out: Vec<(String, u16)> = Vec::new();
    for part in text
        .split(|c: char| c == ',' || c.is_whitespace())
        .filter(|p| !p.is_empty())
    {
        let (addr, weight) = part
            .split_once(':')
            .ok_or_else(|| format!("SignerEntries: {part:?} is not addr:weight"))?;
        FieldKind::Address
            .validate(addr)
            .map_err(|e| format!("SignerEntries: {addr}: {e}"))?;
        let weight = weight
            .parse::<u16>()
            .ok()
            .filter(|w| *w >= 1)
            .ok_or_else(|| format!("SignerEntries: weight for {addr} must be 1..=65535"))?;
        if out.iter().any(|(a, _)| a == addr) {
            return Err(format!("SignerEntries: {addr} listed twice"));
        }
        out.push((addr.to_string(), weight));
    }
    if out.len() > MAX_SIGNERS {
        return Err(format!("SignerEntries: at most {MAX_SIGNERS} signers"));
    }
    Ok(out)
}

fn signer_list_check(f: &Fields) -> Result<(), String> {
    let quorum: u32 = val(f, "SignerQuorum")
        .and_then(|v| v.parse().ok())
        .unwrap_or(0);
    let entries = val(f, "SignerEntries")
        .map(parse_signer_entries)
        .transpose()?
        .unwrap_or_default();
    match (quorum, entries.is_empty()) {
        (0, true) => Ok(()),
        (0, false) => {
            Err("SignerQuorum: 0 deletes the list, so SignerEntries must be blank".into())
        }
        (_, true) => Err("SignerEntries: required unless SignerQuorum is 0 (delete)".into()),
        (q, false) => {
            let sum: u32 = entries.iter().map(|(_, w)| u32::from(*w)).sum();
            if q > sum {
                Err(format!("SignerQuorum: {q} exceeds the total weight {sum}"))
            } else {
                Ok(())
            }
        }
    }
}

fn signer_list_tx(
    account: &str,
    f: &Fields,
    sequence: u32,
    fee_lls: Option<(u32, u32)>,
) -> color_eyre::Result<SignerListSet<'static>> {
    let entries = val(f, "SignerEntries")
        .map(parse_signer_entries)
        .transpose()
        .map_err(|e| eyre!(e))?
        .map(|v| {
            v.into_iter()
                .map(|(account, signer_weight)| SignerEntry {
                    account,
                    signer_weight,
                })
                .collect()
        });
    Ok(SignerListSet {
        common_fields: common_fields!(account, SignerListSet, sequence, fee_lls),
        signer_quorum: uint(f, "SignerQuorum")?.ok_or_else(|| eyre!("SignerQuorum: required"))?,
        signer_entries: entries,
    })
}

json_and_sign!(
    signer_list_tx,
    signer_list_json,
    signer_list_sign,
    "SignerListSet"
);

