pub const CLAWBACK: TxSpec = TxSpec {
    tx_type: "Clawback",
    family: FAMILY,
    summary: "issuer claws back an issued token from a holder ⚠ irreversible",
    fields: &[FieldSpec {
        name: "Amount",
        kind: FieldKind::Amount,
        required: true,
        help: "CUR:holder:value — the issuer slot is the HOLDER's address (you are the issuer; needs AllowTrustLineClawback)",
        default: "",
    }],
    confirm: Some(Confirm {
        phrase: "CLAWBACK",
        hint: "Irreversible: the holder's balance is taken back to you",
    }),
    check: clawback_check,
    build_json: clawback_json,
    sign: clawback_sign,
};

fn clawback_check(f: &Fields) -> Result<(), String> {
    if val(f, "Amount").is_some_and(|v| v.starts_with("XRP:")) {
        return Err("Amount: XRP cannot be clawed back (use CUR:holder:value)".into());
    }
    Ok(())
}

fn clawback_tx(
    account: &str,
    f: &Fields,
    sequence: u32,
    fee_lls: Option<(u32, u32)>,
) -> color_eyre::Result<Clawback<'static>> {
    Ok(Clawback {
        common_fields: common_fields!(account, Clawback, sequence, fee_lls),
        amount: parse_offer_amount(required(f, "Amount")?)?,
        holder: None,
    })
}

json_and_sign!(clawback_tx, clawback_json, clawback_sign, "Clawback");

